// The shape session-band's pane, band and status line share, and the pure text built from it.
import type { SessionRateLimit } from 'claude-code'

import { describeCompactPoint } from './auto-compact-policy'
import type { CompactPoint, CompactSetting } from './auto-compact-policy'
import { formatCountdown, formatTokens, formatUsd } from './cache-math'
import type { InputPrice } from './cache-math'

export type KeeperConfig = {
  cacheTtl: string
  warnMs: number
  inputPricePerMTok: number
  handoffCommand: string
  autoCompact: CompactSetting | 'auto'
  /** /compact's argument for the 📦 button and auto-compact; empty for Claude Code's default summary. */
  compactInstructions: string
  /** Skill the 📝 button runs to update the project's working notes; empty sends a built-in prompt. */
  saveCommand: string
  /** Prompt the 🧭 button sends to ask where the work stands; empty sends a built-in prompt. */
  statusPrompt: string
