  /** Skill the rules belong to: the toggle shows only while it is installed; empty shows it always. */
  styleSkill: string
}

/** empty: nothing cached yet · running: a turn keeps it warm · cooling: inside the warning window. */
export type CachePhase = 'empty' | 'running' | 'warm' | 'cooling' | 'cold'

export type TtlSource = 'config' | 'observed' | 'assumed'

export type KeeperView = {
  phase: CachePhase
  /** The main loop's model, as /model shows it. */
  model: string
  now: number
  remainingMs: number
  ttlMs: number
  ttlSource: TtlSource
  touchAt: number | null
  contextTokens: number
  contextWindow: number
  contextPercent?: number
  rewarmUsd: number
  priceSource: InputPrice['source']
  rateLimits: SessionRateLimit[]
  costUsd?: number
